CREATE TYPE seat_type AS ENUM ('LOWER', 'MIDDLE', 'UPPER', 'SIDE_LOWER', 'SIDE_UPPER');
CREATE TYPE schedule_status AS ENUM ('ACTIVE', 'CANCELLED');
CREATE TABLE IF NOT EXISTS stations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE, code text NOT NULL UNIQUE, city text NOT NULL, state text, created_at timestamp NOT NULL DEFAULT now(), updated_at timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS trains (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), train_number text NOT NULL UNIQUE, train_name text NOT NULL, coach_name text NOT NULL DEFAULT 'AC', total_seats integer NOT NULL, created_at timestamp NOT NULL DEFAULT now(), updated_at timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS seats (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), train_id uuid NOT NULL REFERENCES trains(id) ON DELETE CASCADE, seat_number integer NOT NULL, seat_type seat_type NOT NULL, price real NOT NULL, CONSTRAINT seats_train_seat_number_unique UNIQUE(train_id, seat_number));
CREATE TABLE IF NOT EXISTS routes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), train_id uuid NOT NULL UNIQUE REFERENCES trains(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS route_stations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), route_id uuid NOT NULL REFERENCES routes(id) ON DELETE CASCADE, station_id uuid NOT NULL REFERENCES stations(id) ON DELETE CASCADE, sequence_number integer NOT NULL, arrival_time text, departure_time text, distance_from_origin real NOT NULL DEFAULT 0, CONSTRAINT route_stations_route_sequence_unique UNIQUE(route_id, sequence_number), CONSTRAINT route_stations_route_station_unique UNIQUE(route_id, station_id));
CREATE TABLE IF NOT EXISTS schedules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), train_id uuid NOT NULL REFERENCES trains(id) ON DELETE CASCADE, departure_date date NOT NULL, status schedule_status NOT NULL DEFAULT 'ACTIVE', created_at timestamp NOT NULL DEFAULT now(), updated_at timestamp NOT NULL DEFAULT now(), CONSTRAINT schedules_train_date_unique UNIQUE(train_id, departure_date));
CREATE TABLE IF NOT EXISTS outbox_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), topic text NOT NULL, key text, value jsonb NOT NULL, headers jsonb NOT NULL DEFAULT '{}'::jsonb, status text NOT NULL DEFAULT 'PENDING', retry_count integer NOT NULL DEFAULT 0, max_retries integer NOT NULL DEFAULT 5, created_at timestamp NOT NULL DEFAULT now(), processed_at timestamp, last_error text);
